export type TransformOptions = {
    format?: boolean;
    /**
     * When set, only records belonging to these tables (and their descendants) are considered.
     * This is the expanded set including the hierarchy.
     */
    tables?: string[] | Set<string>;
    /**
     * The original requested parent tables (before hierarchy expansion).
     * When set, child records are only transformed if their parent record is present
     * and being transformed. This prevents orphaned child records from being transformed
     * when their parent is not in scope.
     */
    requestedTables?: string[] | Set<string>;
};
